+/// «Иванов Пётр» → «И. П.»
+pub fn initials(owner: &Owner) -> String {
+    let parts: Vec<&str> = owner.full_name.split_whitespace().collect();
+
+    let last = parts[0];
+    let first = parts[1];
+
+    format!(
+        "{}. {}.",
+        last.chars().next().unwrap_or(' '),
+        first.chars().next().unwrap_or(' ')
+    )
 }

 pub fn short_name(owner: &Owner) -> String {
     owner.full_name.split_whitespace().next().unwrap_or("").to_string()
 }
